#!/usr/bin/env bash
# generate-pkgbuild.sh — generate PKGBUILD + .SRCINFO for a given version
#
# Usage:
#   bash dist/arch/generate-pkgbuild.sh <version>
#
# Example:
#   bash dist/arch/generate-pkgbuild.sh v0.4.0
#
# Output:
#   Writes PKGBUILD and .SRCINFO to stdout (or to a directory with --out)

set -euo pipefail

if [ $# -lt 1 ]; then
  echo "Usage: $0 <version> [--out <dir>]"
  echo "  version — e.g. v0.4.0"
  echo "  --out   — write files to directory instead of stdout"
  exit 1
fi

VERSION="${1#v}"              # strip leading v: v0.4.0 -> 0.4.0
TAG="v$VERSION"
OUT_DIR=""

shift
while [ $# -gt 0 ]; do
  case "$1" in
    --out) OUT_DIR="$2"; shift 2 ;;
    *) echo "Unknown arg: $1"; exit 1 ;;
  esac
done

# The two files below are generated from these, not typed out twice:
# the PKGBUILD said cava was needed and the .SRCINFO did not, which is
# the list helpers actually read.
DEPENDS=(mpv yt-dlp ffmpeg cava)
MAKEDEPENDS=("go>=1.22")

TARBALL="https://github.com/anas1412/ytmgo/archive/$TAG.tar.gz"

# makepkg verifies the source against this. It was SKIP, which verifies
# nothing: a truncated or substituted tarball built silently. GitHub
# generates these archives on demand but the bytes for a given tag are
# stable, so the hash can be pinned like any other source.
echo "Hashing $TARBALL …" >&2
SHA256="$(curl -fsSL "$TARBALL" | sha256sum | cut -d' ' -f1)"
if [ -z "$SHA256" ] || [ "$SHA256" = "$(printf '' | sha256sum | cut -d' ' -f1)" ]; then
  echo "error: could not hash $TARBALL — refusing to generate a package that verifies nothing" >&2
  exit 1
fi
echo "  sha256 $SHA256" >&2

# ---- PKGBUILD ----
read -r -d '' PKGBUILD << PKGBUILD_EOF || true
# Maintainer: Anas <anas1412@github>
# Contributor: Anas <anas1412@github>
# Arch User Repository (AUR) package for ytmgo
# https://aur.archlinux.org/packages/ytmgo
# Auto-generated by dist/arch/generate-pkgbuild.sh

pkgname=ytmgo
pkgver=$VERSION
pkgrel=1
pkgdesc="A terminal-based YouTube Music client — search, download, queue, and play music from the keyboard"
arch=('x86_64' 'aarch64')
url="https://github.com/anas1412/ytmgo"
license=('MIT')
depends=($(printf "'%s' " "${DEPENDS[@]}" | sed 's/ $//'))
makedepends=($(printf "'%s' " "${MAKEDEPENDS[@]}" | sed 's/ $//'))
source=("\$url/archive/v\$pkgver.tar.gz")
sha256sums=('$SHA256')

build() {
  cd "\$srcdir/\$pkgname-\$pkgver"
  CGO_ENABLED=0 go build \\
    -trimpath \\
    -ldflags="-s -w -X ytmgo/internal/version.Version=v\$pkgver" \\
    -o ytmgo .
}

check() {
  cd "\$srcdir/\$pkgname-\$pkgver"
  ./ytmgo --version 2>&1 | grep -q "v\$pkgver"
}

package() {
  cd "\$srcdir/\$pkgname-\$pkgver"
  install -Dm755 ytmgo "\$pkgdir/usr/bin/ytmgo"
  install -Dm644 ytmgo-icon.png "\$pkgdir/usr/share/icons/hicolor/256x256/apps/ytmgo.png"
  # MIT carries its own copyright line, so Arch wants the text shipped
  # rather than pointed at /usr/share/licenses/common.
  install -Dm644 LICENSE "\$pkgdir/usr/share/licenses/\$pkgname/LICENSE"
  install -Dm644 /dev/stdin "\$pkgdir/usr/share/applications/ytmgo.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=ytmgo
Comment=YouTube Music from the Terminal
Exec=ytmgo
Icon=ytmgo
Terminal=true
Categories=AudioVideo;Audio;Music;Player;
Keywords=music;youtube;player;terminal;tui;audio;
StartupNotify=false
EOF
}
PKGBUILD_EOF

# ---- .SRCINFO ----
read -r -d '' SRCINFO << SRCINFO_EOF || true
pkgbase = ytmgo
	pkgdesc = A terminal-based YouTube Music client — search, download, queue, and play music from the keyboard
	pkgver = $VERSION
	pkgrel = 1
	url = https://github.com/anas1412/ytmgo
	arch = x86_64
	arch = aarch64
	license = MIT
$(printf '\tmakedepends = %s\n' "${MAKEDEPENDS[@]}")
$(printf '\tdepends = %s\n' "${DEPENDS[@]}")
	source = https://github.com/anas1412/ytmgo/archive/v$VERSION.tar.gz
	sha256sums = $SHA256

pkgname = ytmgo
SRCINFO_EOF

# ---- Output ----
if [ -n "$OUT_DIR" ]; then
  mkdir -p "$OUT_DIR"
  echo "$PKGBUILD" > "$OUT_DIR/PKGBUILD"
  echo "$SRCINFO" > "$OUT_DIR/.SRCINFO"
  echo "Generated for v$VERSION:"
  echo "  $OUT_DIR/PKGBUILD"
  echo "  $OUT_DIR/.SRCINFO"
else
  echo "============================================"
  echo " PKGBUILD"
  echo "============================================"
  echo "$PKGBUILD"
  echo ""
  echo "============================================"
  echo " .SRCINFO"
  echo "============================================"
  echo "$SRCINFO"
fi
